Here is a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text:
```cpp
#include <string>
#include <iostream>
#include <regex>

std::string convert_markdown_to_html(const std::string& markdown) {
    // Create a regular expression to match all HTML tags
    const std::regex html_tag_regex("<(/?\\w+)(\\s+\\w+(\\s*=\\s*(\"[^\"]*\"|\'[^\']*\'))?)*\\s*/?>");

    // Replace all HTML tags in the input text with their corresponding entities
    std::string html = std::regex_replace(markdown, html_tag_regex, [&html_tag_regex](const std::smatch& match) {
        // The matched HTML tag
        const std::string tag = match.str(1);

        // The inner content of the HTML tag
        const std::string content = match.str(0).substr(1 + tag.length());
        return std::regex_replace(content, html_tag_regex, [](const std::smatch&) { return "&" + std::string{match.str(2)} + ";"; });
    });

    // Replace Markdown special characters with their corresponding HTML entities
    html = std::regex_replace(html, std::regex(R"([\*\_\{\}\[\]\(\)\#\+\-\.\!\|\<\>\=\{\}])"), [](const std::smatch& match) {
        const std::string character = match.str(0);
        return std::string("&") + character + ";;";
    });

    return html;
}
```
This function uses regular expressions to replace all HTML tags with their corresponding entity references. It then replaces Markdown special characters with their corresponding HTML entities. The function returns the resulting HTML formatted text.

